def isCircle(N, A):
    from collections import defaultdict

    in_degree = defaultdict(int)
    out_degree = defaultdict(int)

    for s in A:
        out_degree[s[0]] += 1
        in_degree[s[-1]] += 1

    start_count = sum(1 for count in out_degree.values() if count == 1)
    end_count = sum(1 for count in in_degree.values() if count == 1)

    if start_count != end_count or start_count not in [0, 2]:
        return 0

    visited = set()
    stack = [A[0][0]]

    while stack:
        node = stack.pop()
        if node in visited:
            continue
        visited.add(node)
        found = False
        for s in A:
            if s[0] == node:
                stack.append(s[-1])
                found = True
        if not found:
            break

    return 1 if len(visited) == N else 0
